mapper.select:
SELECT u.user_id, u.user_nm, u.dept_code, u.emp_no, u.email, u.grade_cd, u.use_yn, COALESCE(d.dept_name, '') AS dept_name, COALESCE(g.code_name, '') AS grade_nm, (SELECT STRING_AGG(ur.role_cd, ',' ORDER BY ur.role_cd) FROM tb_user_role ur WHERE ur.user_id = u.user_id) AS role_cds FROM tb_user u LEFT JOIN tb_dept d ON u.dept_code = d.dept_code LEFT JOIN tb_code g ON g.grp_code = 'GRADE' AND g.code = u.grade_cd
AND (u.user_id LIKE '%' || #{keyword} || '%' OR u.user_nm LIKE '%' || #{keyword} || '%' OR u.emp_no LIKE '%' || #{keyword} || '%' OR u.email LIKE '%' || #{keyword} || '%')
AND u.use_yn = #{useYn}
AND u.dept_code = #{deptCode}
AND u.grade_cd = #{gradeCd}
ORDER BY u.user_id

