UPDATE tb_user
SET emp_no = #{empNo},
    email = #{email},
    user_pw = #{userPw}
WHERE user_id = #{userId}

UPDATE tb_user
SET user_pw = #{userPw}
WHERE user_id = #{userId}

UPDATE tb_role
SET role_nm = #{roleNm}, description = #{description}, use_yn = #{useYn}
WHERE role_cd = #{roleCd}

UPDATE tb_menu
SET menu_nm = #{menuNm}, parent_id = #{parentId}, menu_type = #{menuType},
    pgm_id = #{pgmId}, url = #{url}, sort_order = #{sortOrder}, use_yn = #{useYn}
WHERE menu_id = #{menuId}
